{$ param max_width label="Max Width (px)" default="1100" description="Maximum content width in pixels." $}
{$ param padding_y label="Vertical Padding Class" default="py-8" description="Tailwind vertical-padding utility (e.g. py-4, py-8, py-16)." $}
{$ param bg_class label="Background Class" default="" description="Optional tailwind background class (e.g. bg-bg-cool, bg-primary-dark text-white)." $}

<section class="ss-container mx-auto {$= padding_y $} {$= bg_class $}" style="max-width: {$= max_width $}px;">
  {$ slot content $}
    <p class="ss-text">Drop components here.</p>
  {$ /slot $}
</section>
